-- SINH TỰ ĐỘNG từ src/lib/content — không sửa tay. Sửa nội dung trong file nguồn rồi sinh lại.
-- Nạp bài tập Lớp 1: Học kì 1 (Toán, Tiếng Việt: Kết nối tri thức; Tiếng Anh: Global Success) và Toán Học kì 2 (Bài 21–41)
-- và 12 đề ôn tập theo cấp độ L1–L5 (ngân hàng câu hỏi EduChain Kids, src/lib/content/ngan-hang-lop1.ts).
-- Yêu cầu: đã chạy migration 0001 → 0006 và đã có ít nhất 1 tài khoản system_admin.
-- Bài đã nạp từ lần trước (cùng seed_id) được bỏ qua, chỉ thêm bài mới.

-- Bài 1 · Bài 1. Các số 0, 1, 2, 3, 4, 5 (10 câu)
do $$
declare v_admin uuid; v_lesson uuid; v_q uuid;
begin
  select user_id into v_admin from public.user_roles where role = 'system_admin' order by created_at limit 1;
  if v_admin is null then raise exception 'Cần có ít nhất 1 tài khoản system_admin trước khi nạp bài tập'; end if;
  if exists (select 1 from public.lessons where content ->> 'seed_id' = 'toan1-kntt-b01') then return; end if;
  select s.id, 'Bài 1. Các số 0, 1, 2, 3, 4, 5', '{"seed_id":"toan1-kntt-b01","kind":"book","book":"Kết nối tri thức","ref":"Bài 1","unit_code":"KNTT.T1.CD1","unit_title":"Chủ đề 1. Các số từ 0 đến 10","description":"Đếm, đọc, viết các số từ 0 đến 5."}'::jsonb, 'review', v_admin, 'Kết nối tri thức', 1, 1, (select id from public.curriculum_topics where code = 'T1.SO')
  from public.subjects s where s.code = 'toan-1' returning id into v_lesson;
end $$;

